  border: 1px solid rgba(74, 222, 128, 0.4);
  border-radius: 10px;
  padding: 12px 16px;
  font-weight: 600;
}

.newsletter__submit {
  align-self: flex-end;
}

/* ===== Footer ===== */
.site-footer {
  background: #08090b;
  color: var(--text-muted);
  padding: 56px 0 24px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 32px;
  margin-bottom: 32px;
}

.footer-col__title {
  color: var(--text);
  font-size: 0.9375rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 700;
  margin: 0 0 14px;
}

.footer-col__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.footer-col__list a {
  color: var(--text-muted);
  text-decoration: none;
}

.footer-col__list a:hover {
  color: var(--text);
  text-decoration: underline;
}

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 20px;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  font-size: 0.875rem;
  color: var(--text-subtle);
}

.footer-social {
  display: flex;
  gap: 8px;
