  margin: 0;
  padding: 0;
}

/* ===== Live region ===== */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ===== Reflow / responsive ===== */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .editorial-grid {
    grid-template-columns: 1fr 1fr;
  }
  .editorial-card--feature {
    grid-row: auto;
    grid-column: span 2;
  }
  .editorial-card--feature .editorial-card__media {
    aspect-ratio: 16 / 9;
  }
  .category-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .hero__inner {
    grid-template-columns: 1fr;
    padding: 48px 20px;
    gap: 32px;
  }
  .hero__visual {
    aspect-ratio: 4 / 3;
  }
  .deal-banner {
    grid-template-columns: 1fr;
    padding: 24px;
  }
  .product-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .editorial-grid {
    grid-template-columns: 1fr;
  }
  .editorial-card--feature {
    grid-column: auto;
  }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
  .section {
    padding: 56px 0;
  }
  .primary-nav {
    display: none;
  }
}

@media (max-width: 480px) {
  .category-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .product-grid {
    grid-template-columns: 1fr;
  }
  .footer-grid {
    grid-template-columns: 1fr;
  }
  .newsletter__form {
    flex-direction: column;
    align-items: stretch;
  }
  .newsletter__submit {
    align-self: stretch;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* Forced colors */
@media (forced-colors: active) {
  .product-card,
  .editorial-card,
  .category-tile,
  .deal-banner,
  .hero__visual,
  .countdown__unit,
  .newsletter__input {
    border: 1px solid CanvasText;
  }
  .icon-btn {
    border: 1px solid ButtonBorder;
    color: ButtonText;
  }
}
