+  --info: #7cc4ff;
+  --focus: #9ad1ff;
+  --radius: 10px;
+  --radius-lg: 16px;
+  --shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
+  --maxw: 1240px;
+}
+
+* {
+  box-sizing: border-box;
+}
+
+html {
+  -webkit-text-size-adjust: 100%;
+}
+
+body {
+  margin: 0;
+  font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
+  background: var(--bg);
+  color: var(--text);
+  line-height: 1.5;
+  min-height: 100vh;
+  overflow-wrap: anywhere;
+}
+
+img,
+svg {
+  display: block;
+  max-width: 100%;
+}
+
+a {
+  color: var(--info);
+  text-decoration: none;
+}
+
+a:hover {
+  text-decoration: underline;
+}
+
+button {
+  font-family: inherit;
+  cursor: pointer;
+}
+
+/* Focus styles (visible across all states) */
+:focus-visible {
+  outline: 2px solid var(--focus);
+  outline-offset: 2px;
+  border-radius: 4px;
+}
+
+/* Skip link */
+.skip-link {
+  position: absolute;
+  left: -9999px;
+  top: 0;
+  background: var(--accent);
+  color: var(--accent-ink);
+  padding: 12px 16px;
+  font-weight: 700;
+  z-index: 1000;
+  border-radius: 0 0 8px 0;
+}
+
+.skip-link:focus {
+  left: 0;
+}
+
+/* ===== Layout ===== */
+.container {
+  max-width: var(--maxw);
+  margin: 0 auto;
+  padding: 0 20px;
+}
+
+/* ===== Announcement bar ===== */
+.announcement {
+  background: linear-gradient(90deg, #2a1d0a, #1a1308);
+  color: var(--accent-hover);
+  font-size: 0.875rem;
+  border-bottom: 1px solid var(--border);
+}
+
+.announcement__inner {
+  padding: 10px 20px;
+  text-align: center;
+  font-weight: 500;
+}
+
+.announcement strong {
+  color: var(--accent);
+}
+
+/* ===== Header ===== */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 50;
+  background: rgba(11, 13, 16, 0.92);
+  backdrop-filter: blur(8px);
+  border-bottom: 1px solid var(--border);
+}
+
+.site-header__inner {
+  display: flex;
+  align-items: center;
+  gap: 24px;
+  padding: 16px 20px;
+}
+
+.brand {
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  color: var(--text);
+  font-weight: 800;
+  font-size: 1.25rem;
+  letter-spacing: 0.02em;
+  text-decoration: none;
+}
+
+.brand:hover {
+  text-decoration: none;
+}
+
+.brand__mark {
+  width: 32px;
+  height: 32px;
+  border-radius: 8px;
+  background: linear-gradient(135deg, var(--accent), #d97757);
+  display: grid;
+  place-items: center;
+  color: var(--accent-ink);
+  font-weight: 900;
+}
+
+.primary-nav {
+  flex: 1;
+  min-width: 0;
+}
+
+.primary-nav__list {
+  list-style: none;
+  display: flex;
+  gap: 4px;
+  margin: 0;
+  padding: 0;
+  flex-wrap: wrap;
+}
+
+.primary-nav__link {
+  display: inline-block;
+  padding: 8px 12px;
+  color: var(--text-muted);
+  font-weight: 500;
+  border-radius: 8px;
+  text-decoration: none;
+}
+
+.primary-nav__link:hover,
+.primary-nav__link[aria-current="page"] {
+  background: var(--surface-2);
+  color: var(--text);
+  text-decoration: none;
+}
+
+.header-actions {
+  display: flex;
+  align-items: center;
+  gap: 4px;
+}
+
+.icon-btn {
+  position: relative;
+  background: transparent;
+  border: 1px solid transparent;
+  color: var(--text-muted);
+  padding: 8px;
+  border-radius: 8px;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  min-width: 40px;
+  min-height: 40px;
+}
+
+.icon-btn:hover {
+  background: var(--surface-2);
+  color: var(--text);
+  border-color: var(--border);
+}
+
+.icon-btn__badge {
+  position: absolute;
+  top: 2px;
+  right: 2px;
+  background: var(--accent);
+  color: var(--accent-ink);
+  font-size: 0.6875rem;
+  font-weight: 800;
+  padding: 1px 5px;
+  border-radius: 10px;
+  min-width: 16px;
+  text-align: center;
+  line-height: 1.2;
+}
+
+/* ===== Hero ===== */
+.hero {
+  position: relative;
+  overflow: hidden;
+  background:
+    radial-gradient(1200px 500px at 80% -20%, rgba(255, 184, 77, 0.18), transparent 60%),
+    radial-gradient(900px 400px at 0% 100%, rgba(124, 196, 255, 0.12), transparent 60%),
+    linear-gradient(180deg, #0d1014, #0b0d10);
+  border-bottom: 1px solid var(--border);
+}
+
+.hero__inner {
+  display: grid;
+  grid-template-columns: 1.1fr 1fr;
+  gap: 48px;
+  align-items: center;
+  padding: 72px 20px;
+}
+
+.hero__eyebrow {
+  display: inline-block;
+  font-size: 0.8125rem;
+  font-weight: 600;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  color: var(--accent);
+  margin-bottom: 18px;
+}
+
+.hero__title {
+  font-size: clamp(2rem, 4vw, 3.5rem);
+  line-height: 1.1;
+  margin: 0 0 18px;
+  letter-spacing: -0.02em;
+}
+
+.hero__title em {
+  font-style: normal;
+  background: linear-gradient(120deg, var(--accent), #ff8c66);
+  -webkit-background-clip: text;
+  background-clip: text;
+  color: transparent;
+}
+
+@media (forced-colors: active) {
+  .hero__title em {
+    color: CanvasText;
+    background: none;
+    -webkit-text-fill-color: CanvasText;
+  }
+}
+
+.hero__lead {
+  font-size: 1.125rem;
+  color: var(--text-muted);
+  margin: 0 0 28px;
+  max-width: 56ch;
+}
+
+.hero__ctas {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 12px;
+}
+
+.hero__meta {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 24px;
+  margin-top: 36px;
+  padding-top: 24px;
+  border-top: 1px solid var(--border);
+}
+
+.hero__meta-item {
+  display: flex;
+  flex-direction: column;
+}
+
+.hero__meta-num {
+  font-size: 1.5rem;
+  font-weight: 800;
+  color: var(--text);
+}
+
+.hero__meta-label {
+  font-size: 0.875rem;
+  color: var(--text-subtle);
+}
+
+.hero__visual {
+  position: relative;
+  aspect-ratio: 4 / 5;
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  background: linear-gradient(140deg, #2a1d0a, #1a1308 60%, #0b0d10);
+  border: 1px solid var(--border);
+  box-shadow: var(--shadow);
+}
+
+.hero__visual-art {
+  position: absolute;
+  inset: 0;
+  background:
+    radial-gradient(circle at 30% 30%, rgba(255, 184, 77, 0.45), transparent 55%),
+    radial-gradient(circle at 75% 75%, rgba(255, 140, 102, 0.35), transparent 55%),
+    linear-gradient(160deg, #2a1d0a 0%, #1a1308 50%, #0b0d10 100%);
+}
+
+.hero__visual-card {
+  position: absolute;
+  bottom: 24px;
+  left: 24px;
+  right: 24px;
+  background: rgba(20, 24, 29, 0.85);
+  backdrop-filter: blur(8px);
+  border: 1px solid var(--border-strong);
+  border-radius: 12px;
+  padding: 16px 20px;
+  display: flex;
+  align-items: center;
+  gap: 16px;
+}
+
+.hero__visual-card-text {
+  flex: 1;
+  min-width: 0;
+}
+
+.hero__visual-card-title {
+  font-weight: 700;
+  margin: 0 0 2px;
+}
+
+.hero__visual-card-meta {
+  color: var(--text-muted);
+  font-size: 0.875rem;
+  margin: 0;
+}
+
+.hero__visual-card-price {
+  font-weight: 800;
+  color: var(--accent);
+  font-size: 1.125rem;
+  white-space: nowrap;
+}
+
+/* ===== Buttons ===== */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+  padding: 12px 20px;
+  border-radius: 10px;
+  font-weight: 600;
+  font-size: 0.9375rem;
+  border: 1px solid transparent;
+  text-decoration: none;
+  transition: background 0.15s, border-color 0.15s, transform 0.05s;
+  min-height: 44px;
+}
+
+.btn:hover {
+  text-decoration: none;
+}
+
+.btn:active {
+  transform: translateY(1px);
+}
+
+.btn--primary {
+  background: var(--accent);
+  color: var(--accent-ink);
+  border-color: var(--accent);
+}
+
+.btn--primary:hover {
+  background: var(--accent-hover);
+  border-color: var(--accent-hover);
+}
+
+.btn--secondary {
+  background: var(--surface-2);
+  color: var(--text);
+  border-color: var(--border-strong);
+}
+
+.btn--secondary:hover {
+  background: var(--surface-3);
+  border-color: #4a5666;
+}
+
+.btn--ghost {
+  background: transparent;
+  color: var(--text);
+  border-color: var(--border-strong);
+}
+
+.btn--ghost:hover {
+  background: var(--surface-2);
+}
+
+@media (forced-colors: active) {
+  .btn {
+    border: 1px solid ButtonBorder;
+  }
+}
+
+/* ===== Section ===== */
+.section {
+  padding: 72px 0;
+  border-bottom: 1px solid var(--border);
+}
+
+.section__head {
+  display: flex;
+  align-items: end;
+  justify-content: space-between;
+  gap: 16px;
+  margin-bottom: 32px;
+  flex-wrap: wrap;
+}
+
+.section__title {
+  font-size: clamp(1.5rem, 2.5vw, 2rem);
+  margin: 0 0 6px;
+  letter-spacing: -0.01em;
+}
+
+.section__subtitle {
+  color: var(--text-muted);
+  margin: 0;
+  max-width: 60ch;
+}
+
+.section__link {
+  font-weight: 600;
+  color: var(--accent);
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+}
+
+.section__link:hover {
+  color: var(--accent-hover);
+  text-decoration: none;
+}
+
+/* ===== Category strip ===== */
+.categories {
+  padding: 32px 0;
+  border-bottom: 1px solid var(--border);
+}
+
+.category-grid {
+  list-style: none;
+  margin: 0;
+  padding: 0;
+  display: grid;
+  grid-template-columns: repeat(6, minmax(0, 1fr));
+  gap: 12px;
+}
+
+.category-tile {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  justify-content: center;
+  gap: 10px;
+  padding: 18px 12px;
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  color: var(--text);
+  text-decoration: none;
+  text-align: center;
+  font-weight: 500;
+  font-size: 0.9375rem;
+  min-height: 110px;
+  transition: border-color 0.15s, background 0.15s, transform 0.1s;
+}
+
+.category-tile:hover {
+  border-color: var(--border-strong);
+  background: var(--surface-2);
+  text-decoration: none;
+  transform: translateY(-2px);
+}
+
+.category-tile__icon {
+  width: 32px;
+  height: 32px;
+  color: var(--accent);
+}
+
+/* ===== Product grid ===== */
+.product-grid {
+  list-style: none;
+  margin: 0;
+  padding: 0;
+  display: grid;
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+  gap: 20px;
+}
+
+.product-card {
+  display: flex;
+  flex-direction: column;
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  transition: border-color 0.15s, transform 0.15s;
+}
+
+.product-card:hover {
+  border-color: var(--border-strong);
+  transform: translateY(-3px);
+}
+
+.product-card__media {
+  position: relative;
+  aspect-ratio: 1 / 1;
+  background: var(--surface-2);
+  overflow: hidden;
+}
+
+.product-card__art {
+  position: absolute;
+  inset: 0;
+}
+
+.product-card__badges {
+  position: absolute;
+  top: 12px;
+  left: 12px;
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+  align-items: flex-start;
+}
+
+.badge {
+  font-size: 0.75rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: 0.06em;
+  padding: 4px 10px;
+  border-radius: 999px;
+  border: 1px solid transparent;
+}
+
+.badge--new {
+  background: rgba(124, 196, 255, 0.15);
+  color: var(--info);
+  border-color: rgba(124, 196, 255, 0.35);
+}
+
+.badge--sale {
+  background: rgba(255, 107, 107, 0.15);
+  color: var(--danger);
+  border-color: rgba(255, 107, 107, 0.35);
+}
+
+.badge--limited {
+  background: rgba(255, 184, 77, 0.15);
+  color: var(--accent);
+  border-color: rgba(255, 184, 77, 0.4);
+}
+
+.product-card__wishlist {
+  position: absolute;
+  top: 10px;
+  right: 10px;
+  width: 36px;
+  height: 36px;
+  border-radius: 50%;
+  background: rgba(11, 13, 16, 0.7);
+  border: 1px solid var(--border);
+  color: var(--text);
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+}
+
+.product-card__wishlist:hover {
+  background: rgba(20, 24, 29, 0.9);
+  color: var(--accent);
+  border-color: var(--border-strong);
+}
+
+.product-card__wishlist[aria-pressed="true"] {
+  color: var(--danger);
+  border-color: rgba(255, 107, 107, 0.5);
+}
+
+.product-card__body {
+  padding: 16px;
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+  flex: 1;
+}
+
+.product-card__category {
+  font-size: 0.75rem;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  color: var(--text-subtle);
+  font-weight: 600;
+}
+
+.product-card__title {
+  font-size: 1rem;
+  margin: 0;
+  font-weight: 600;
+  line-height: 1.35;
+}
+
+.product-card__title a {
+  color: var(--text);
+  text-decoration: none;
+}
+
+.product-card__title a:hover {
+  color: var(--accent-hover);
+  text-decoration: none;
+}
+
+.product-card__rating {
+  display: flex;
+  align-items: center;
+  gap: 6px;
+  font-size: 0.875rem;
+  color: var(--text-muted);
+}
+
+.product-card__stars {
+  color: var(--accent);
+  letter-spacing: 1px;
+}
+
+.product-card__footer {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+  margin-top: auto;
+  padding-top: 8px;
+}
+
+.price {
+  display: inline-flex;
+  align-items: baseline;
+  gap: 8px;
+}
+
+.price__current {
+  font-size: 1.125rem;
+  font-weight: 800;
+  color: var(--text);
+}
+
+.price__original {
+  font-size: 0.9375rem;
+  color: var(--text-subtle);
+  text-decoration: line-through;
+}
+
+.price__save {
+  margin-left: 4px;
+  font-size: 0.75rem;
+  color: var(--success);
+  font-weight: 700;
+}
+
+.add-to-cart {
+  background: var(--surface-3);
+  color: var(--text);
+  border: 1px solid var(--border-strong);
+  border-radius: 8px;
+  padding: 8px 12px;
+  font-weight: 600;
+  font-size: 0.875rem;
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  min-height: 36px;
+}
+
+.add-to-cart:hover {
+  background: var(--accent);
+  color: var(--accent-ink);
+  border-color: var(--accent);
+}
+
+/* ===== Deals ===== */
+.deals {
+  background: linear-gradient(180deg, #0c0e12, #0b0d10);
+}
+
+.deal-banner {
+  display: grid;
+  grid-template-columns: 1.1fr 1fr;
+  gap: 32px;
+  align-items: center;
+  background:
+    radial-gradient(600px 300px at 100% 0%, rgba(255, 184, 77, 0.15), transparent 60%),
+    linear-gradient(135deg, #1a1308, #14181d);
+  border: 1px solid var(--border-strong);
+  border-radius: var(--radius-lg);
+  padding: 36px;
+  margin-bottom: 32px;
+}
+
+.deal-banner__title {
+  font-size: clamp(1.5rem, 3vw, 2.25rem);
+  margin: 0 0 12px;
+  letter-spacing: -0.01em;
+}
+
+.deal-banner__text {
+  color: var(--text-muted);
+  margin: 0 0 20px;
+}
+
+.countdown {
+  display: flex;
+  gap: 10px;
+  margin-bottom: 24px;
+  flex-wrap: wrap;
+}
+
+.countdown__unit {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: 10px;
+  padding: 12px 14px;
+  min-width: 70px;
+  text-align: center;
+}
+
+.countdown__num {
+  font-size: 1.5rem;
+  font-weight: 800;
+  color: var(--text);
+  font-variant-numeric: tabular-nums;
+  display: block;
+}
+
+.countdown__label {
+  font-size: 0.75rem;
+  text-transform: uppercase;
+  letter-spacing: 0.1em;
+  color: var(--text-subtle);
+}
+
+.deal-banner__visual {
+  aspect-ratio: 4 / 3;
+  background:
+    radial-gradient(circle at 50% 50%, rgba(255, 184, 77, 0.4), transparent 60%),
+    linear-gradient(135deg, #2a1d0a, #1a1308);
+  border-radius: 12px;
+  border: 1px solid var(--border);
+  position: relative;
+  overflow: hidden;
+  display: grid;
+  place-items: center;
+}
+
+.deal-banner__visual-text {
+  font-weight: 900;
+  font-size: clamp(2.5rem, 6vw, 4.5rem);
+  letter-spacing: -0.04em;
+  background: linear-gradient(135deg, var(--accent), #ff8c66);
+  -webkit-background-clip: text;
+  background-clip: text;
+  color: transparent;
+  line-height: 1;
+  text-align: center;
+}
+
+@media (forced-colors: active) {
+  .deal-banner__visual-text {
+    color: CanvasText;
+    background: none;
+    -webkit-text-fill-color: CanvasText;
+  }
+}
+
+/* ===== Editorial ===== */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr 1fr;
+  gap: 20px;
+}
+
+.editorial-card {
+  position: relative;
+  display: flex;
+  flex-direction: column;
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  text-decoration: none;
+  color: var(--text);
+  transition: border-color 0.15s, transform 0.15s;
+}
+
+.editorial-card:hover {
+  border-color: var(--border-strong);
+  text-decoration: none;
+  transform: translateY(-3px);
+}
+
+.editorial-card--feature {
+  grid-row: span 2;
+}
+
+.editorial-card__media {
+  aspect-ratio: 16 / 10;
+  position: relative;
+  overflow: hidden;
+}
+
+.editorial-card--feature .editorial-card__media {
+  aspect-ratio: 4 / 5;
+}
+
+.editorial-card__art {
+  position: absolute;
+  inset: 0;
+}
+
+.editorial-card__art--1 {
+  background:
+    radial-gradient(circle at 25% 25%, rgba(124, 196, 255, 0.4), transparent 50%),
+    linear-gradient(135deg, #1a2a3a, #0d1620);
+}
+
+.editorial-card__art--2 {
+  background:
+    radial-gradient(circle at 75% 30%, rgba(255, 184, 77, 0.35), transparent 60%),
+    linear-gradient(135deg, #2a1d0a, #14181d);
+}
+
+.editorial-card__art--3 {
+  background:
+    radial-gradient(circle at 50% 70%, rgba(74, 222, 128, 0.25), transparent 55%),
+    linear-gradient(135deg, #122016, #0b0d10);
+}
+
+.editorial-card__art--4 {
+  background:
+    radial-gradient(circle at 30% 60%, rgba(217, 119, 87, 0.4), transparent 55%),
+    linear-gradient(135deg, #2a1612, #14181d);
+}
+
+.editorial-card__body {
+  padding: 20px 24px 24px;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+}
+
+.editorial-card__tag {
+  font-size: 0.75rem;
+  text-transform: uppercase;
+  letter-spacing: 0.1em;
+  color: var(--accent);
+  font-weight: 700;
+}
+
+.editorial-card__title {
+  margin: 0;
+  font-size: 1.25rem;
+  line-height: 1.3;
+  letter-spacing: -0.01em;
