      <div className="footer-bottom">
        <span>© 2026 Maven &amp; Co. All rights reserved.</span>
        <nav aria-label="Social media">
          <ul className="footer-social">
            <li>
              <a href="#tw" className="icon-btn" aria-label="Maven & Co. on Twitter">
