              </a>
            </li>
            <li>
              <a href="#ig" className="icon-btn" aria-label="Maven & Co. on Instagram">
                <Icon name="instagram" />
              </a>
            </li>
            <li>
              <a href="#yt" className="icon-btn" aria-label="Maven & Co. on YouTube">
                <Icon name="youtube" />
              </a>
            </li>
          </ul>
        </nav>
      </div>
    </div>
  </footer>
);

/* ===================== App ===================== */

const App = () => {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState(() => new Set());
  const [announcement, setAnnouncement] = useState("");

  const handleAddToCart = useCallback((product) => {
    setCart((prev) => [...prev, product.id]);
    setAnnouncement(`${product.name} added to cart.`);
  }, []);

  const handleWishlist = useCallback((id) => {
    setWishlist((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
        setAnnouncement("Removed from wishlist.");
      } else {
        next.add(id);
        setAnnouncement("Added to wishlist.");
      }
      return next;
    });
  }, []);

  const handleAnnounce = useCallback((msg) => {
    setAnnouncement(msg);
  }, []);

  return (
    <>
      <a href="#main" className="skip-link">Skip to main content</a>
      <AnnouncementBar />
      <Header cartCount={cart.length} wishlistCount={wishlist.size} />
      <main id="main">
        <Hero />
        <CategoryStrip />
        <FeaturedProducts
          wishlist={wishlist}
          onWishlist={handleWishlist}
          onAddToCart={handleAddToCart}
        />
        <Deals
          wishlist={wishlist}
          onWishlist={handleWishlist}
          onAddToCart={handleAddToCart}
        />
        <Editorial />
        <Newsletter onAnnounce={handleAnnounce} />
      </main>
      <Footer />
      <div role="status" aria-live="polite" className="sr-only">
        {announcement}
      </div>
    </>
  );
};

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
