      <ul className="product-grid">
        {FEATURED_PRODUCTS.map((p) => (
          <ProductCard
            key={p.id}
            product={p}
            isWishlisted={wishlist.has(p.id)}
            onWishlist={onWishlist}
            onAddToCart={onAddToCart}
          />
        ))}
      </ul>
    </div>
