const Countdown = ({ targetMs }) => {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const remaining = Math.max(0, targetMs - now);
  const days = Math.floor(remaining / 86400000);
  const hours = Math.floor((remaining % 86400000) / 3600000);
  const minutes = Math.floor((remaining % 3600000) / 60000);
  const seconds = Math.floor((remaining % 60000) / 1000);
  const pad = (n) => String(n).padStart(2, "0");

  return (
    <div
      className="countdown"
      role="timer"
      aria-live="off"
      aria-label={`Sale ends in ${days} days, ${hours} hours, ${minutes} minutes`}
    >
      {[
        { v: days, l: "Days" },
        { v: hours, l: "Hours" },
        { v: minutes, l: "Min" },
        { v: seconds, l: "Sec" },
      ].map((u) => (
        <div className="countdown__unit" key={u.l}>
          <span className="countdown__num">{pad(u.v)}</span>
          <span className="countdown__label">{u.l}</span>
        </div>
      ))}
    </div>
  );
};

