const Newsletter = ({ onAnnounce }) => {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const inputRef = useRef(null);

  const handleSubmit = (e) => {
    e.preventDefault();
    const trimmed = email.trim();
    if (!trimmed) {
      setError("Please enter your email address.");
      setSuccess("");
      inputRef.current?.focus();
      return;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) {
      setError("Please enter a valid email address (e.g. you@example.com).");
      setSuccess("");
      inputRef.current?.focus();
      return;
    }
    setError("");
    setSuccess(`Thanks! We've sent a confirmation to ${trimmed}.`);
    onAnnounce?.(`Subscribed with ${trimmed}`);
    setEmail("");
  };

  return (
    <section className="newsletter" aria-labelledby="news-title">
      <div className="container newsletter__inner">
        <h2 id="news-title" className="newsletter__title">Join the list</h2>
        <p className="newsletter__lead">
          Early access to drops, members-only deals, and our weekly journal — straight to your inbox.
        </p>
        <form className="newsletter__form" onSubmit={handleSubmit} noValidate>
          <div className="newsletter__field">
            <label htmlFor="news-email" className="newsletter__label">
              Email address <span aria-hidden="true" style={{ color: "var(--accent)" }}>*</span>
            </label>
            <input
              ref={inputRef}
              id="news-email"
              type="email"
              className="newsletter__input"
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              aria-required="true"
              aria-invalid={!!error}
              aria-describedby={error ? "news-error" : "news-hint"}
              autoComplete="email"
            />
            {error && (
              <span id="news-error" className="newsletter__error" role="alert">
                {error}
              </span>
            )}
          </div>
          <button type="submit" className="btn btn--primary newsletter__submit">
            Subscribe
          </button>
        </form>
        <p id="news-hint" className="newsletter__hint">
          We'll never share your email. Unsubscribe at any time.
        </p>
        {success && (
          <p className="newsletter__success" role="status">{success}</p>
        )}
      </div>
    </section>
  );
};

